import re
from datetime import date

from django.conf import settings
from django.db import migrations, models
from django.db.models.functions import TruncDate

# A diária já lançada traz a noite na descrição: "Diária 28/10/2026 — 101".
_NOITE = re.compile(r"^Diária (\d{2})/(\d{2})/(\d{4})")


def preencher_competencia(apps, schema_editor):
    """Lançamentos antigos: competência = dia do lançamento (horário de Brasília); a
    diária vai para a noite dela, lida da descrição."""
    LancamentoConta = apps.get_model("reservas", "LancamentoConta")
    LancamentoConta.objects.filter(competencia__isnull=True).update(
        competencia=TruncDate("criado_em"))
    mudar = []
    diarias = LancamentoConta.objects.filter(tipo="diaria").only("pk", "descricao", "competencia")
    for lanc in diarias.iterator():
        achado = _NOITE.match(lanc.descricao)
        if not achado:
            continue  # ex.: "Diferença de tarifa…" fica no dia do lançamento
        dia, mes, ano = (int(x) for x in achado.groups())
        try:
            noite = date(ano, mes, dia)
        except ValueError:
            continue
        if noite != lanc.competencia:
            lanc.competencia = noite
            mudar.append(lanc)
    LancamentoConta.objects.bulk_update(mudar, ["competencia"], batch_size=500)


